import boto3
import datetime
from botocore.config import Config

def get_activations(events, context):
    config = Config(retries={"max_attempts": 5, "mode": "standard"})
    ssm = boto3.client('ssm', config=config)

    kwargs = {'MaxResults': 50}
    if events.get('NextToken') and events.get('NextToken') != '':
        kwargs['NextToken'] = events['NextToken']

    response = ssm.describe_activations(**kwargs)

    # Convert all datetime objects to strings
    activation_list = [
      {
        "ActivationId": activation["ActivationId"],
        "ExpirationDate": activation["ExpirationDate"].astimezone(datetime.timezone.utc).isoformat(),
        "IamRole": activation["IamRole"],
        "RegistrationLimit": activation["RegistrationLimit"],
        "RegistrationsCount": activation["RegistrationsCount"],
      }
      for activation in response.get('ActivationList', [])
    ]
    next_token = response.get('NextToken', '')

    return {
        'ActivationList': activation_list,
        'NextToken': next_token,
        'should_continue': bool(next_token)
    }

def merge_activations(events, context):
    current_activations = events['AllActivations']
    new_activations = events['NewActivations']

    merged = current_activations + new_activations

    return {'MergedActivations': merged}
